"use client";

import { useState, useEffect } from "react";
import { useFinanceData, useSubmit } from "@/lib/api";
import { Card, Skeleton } from "@/components/finance";
import { Button, Input, Slider } from "@/components/finance";
import { motion } from "framer-motion";

const DebtPage = () => {
  const { data: debts, isLoading, isError } = useFinanceData("/api/finance/debt/overview");
  const { mutate, isSubmitting, error } = useSubmit("/api/finance/debt/simulate");

  const [extraPayment, setExtraPayment] = useState(0);
  const [salaryIncrease, setSalaryIncrease] = useState(0);
  const [bonus, setBonus] = useState(0);
  const [monthsSaved, setMonthsSaved] = useState(0);
  const [interestSaved, setInterestSaved] = useState(0);

  useEffect(() => {
    if (debts) {
      const totalOutstanding = debts.reduce((acc, debt) => acc + debt.outstanding, 0);
      const highestInterest = Math.max(...debts.map(debt => debt.interest_rate));
      const nextEMI = debts[0].emi;

      const avalancheCalculator = new AvalancheCalculator();
      const snowballCalculator = new SnowballCalculator();

      const avalancheMonths = avalancheCalculator.calculateMonths(totalOutstanding, highestInterest, nextEMI);
      const snowballMonths = snowballCalculator.calculateMonths(totalOutstanding, highestInterest, nextEMI);

      setMonthsSaved(avalancheMonths);
      setInterestSaved(snowballMonths * nextEMI);
    }
  }, [debts]);

  const handleSimulate = async () => {
    const response = await mutate({ extra_payment: extraPayment, salary_increase: salaryIncrease, bonus: bonus });
    if (response) {
      setMonthsSaved(response.months_saved);
      setInterestSaved(response.interest_saved);
    }
  };

  if (isLoading) return <Skeleton />;
  if (isError) return <div>Error: {error?.message}</div>;

  return (
    <div className="flex flex-col gap-4">
      <Card title="Debt Overview">
        {debts && debts.length === 0 ? (
          <div className="text-center">No debts found.</div>
        ) : (
          <div className="flex flex-col gap-2">
            {debts.map((debt, index) => (
              <div key={index} className="flex justify-between items-center">
                <div>{debt.name}</div>
                <div>{debt.outstanding}</div>
              </div>
            ))}
          </div>
        )}
      </Card>
      <Card title="Payoff Plan">
        <div className="flex flex-col gap-2">
          <div className="flex justify-between items-center">
            <div>Extra Payment:</div>
            <Input type="number" value={extraPayment} onChange={(e) => setExtraPayment(Number(e.target.value))} />
          </div>
          <div className="flex justify-between items-center">
            <div>Salary Increase:</div>
            <Input type="number" value={salaryIncrease} onChange={(e) => setSalaryIncrease(Number(e.target.value))} />
          </div>
          <div className="flex justify-between items-center">
            <div>Bonus:</div>
            <Input type="number" value={bonus} onChange={(e) => setBonus(Number(e.target.value))} />
          </div>
          <Button onClick={handleSimulate} disabled={isSubmitting}>
            Simulate
          </Button>
          <div className="flex justify-between items-center">
            <div>Months Saved:</div>
            <div>{monthsSaved}</div>
          </div>
          <div className="flex justify-between items-center">
            <div>Interest Saved:</div>
            <div>{interestSaved}</div>
          </div>
        </div>
      </Card>
      <Card title="Learning">
        <div className="flex flex-col gap-2">
          <div className="flex justify-between items-center">
            <div>Action:</div>
            <div>Pay off high-interest debt first.</div>
          </div>
          <div className="flex justify-between items-center">
            <div>Reason:</div>
            <div>High-interest debt incurs higher costs over time.</div>
          </div>
          <div className="flex justify-between items-center">
            <div>Learn:</div>
            <div>Consider using the avalanche or snowball method for debt repayment.</div>
          </div>
        </div>
      </Card>
    </div>
  );
};

export default DebtPage;
